Rules.InvariantScript:
Set(varAppView, "SuperAdmin");

Set(varPageKey, "SUPERADMIN");
Set(varPageTitle, "Administration");
Set(varPageSubtitle, "Platform configuration and governance");

Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingSubMsg, "");
Set(varGlobalLoadingScope, "");

With(
    {
        _key: Lower(Trim(Self.SelectedItemKey)),
        _hasProject: !IsBlank(varProjectId),
        _hasConfig: varProjectHasReportConfig || varHomeHiveLoaded || varProjectHasPHRData
    },

    If(
        _key = "superadmin",

        Set(varGlobalLoading, false);
        Set(varGlobalLoadingMsg, "");
        Set(varGlobalLoadingSubMsg, "");
        Set(varGlobalLoadingScope, "");
        Set(varGlobalLoadAction, "");
        Set(varGlobalLoadPending, false);

        Set(varPHR_IsLoading, false);
        Set(varOps_IsLoading, false);
        Set(varTasks_IsLoading, false);
        Set(varPunches_IsLoading, false);
        Set(varCfg_IsLoading, false);

        Set(varAppView, "SuperAdmin");
        Set(varPageKey, "SUPERADMIN");
        Set(varPageTitle, "Administration");
        Set(varPageSubtitle, "Platform configuration and governance");

        Navigate(scr_SuperAdmin, ScreenTransition.None),

        If(
            _key <> "home" && !_hasProject,

            Notify("Please select a project first.", NotificationType.Warning);

            Set(varAppView, "Home");
            Set(varPageKey, "HOME");
            Set(varPageTitle, "Home");
            Set(varPageSubtitle, "Project command center");

            Navigate(scr_Home, ScreenTransition.None),

            If(
                _key in ["overview", "tasks", "punches", "briefing", "config", "skyline"] && !_hasConfig,

                Notify(
                    "This project has no published report configuration yet.",
                    NotificationType.Warning
                );

                Set(varAppView, "Home");
                Set(varPageKey, "HOME");
                Set(varPageTitle, "Home");
                Set(varPageSubtitle, "Project command center");

                Navigate(scr_Home, ScreenTransition.None),

                Switch(
                    _key,

                    "skyline",
                    Set(varAppView, "Skyline");
                    Set(varPageKey, "SKYLINE");
                    Set(varPageTitle, "Delivery Skyline");
                    Set(varPageSubtitle, "Weekly subsystem delivery risk and workload forecast");
                    Set(varSkylineLoaded, false);
                    Set(varSkylineError, "");
                    Clear(colSkylineRaw);
                    Clear(colSkylineWeeks);
                    Clear(colSkylineSelectedWeek);

                    Navigate(scr_Skyline, ScreenTransition.None),


                    "home",
                        Set(varGlobalLoading, false);
                        Set(varGlobalLoadingMsg, "");
                        Set(varGlobalLoadingSubMsg, "");
                        Set(varGlobalLoadingScope, "");
                        Set(varGlobalLoadAction, "");
                        Set(varGlobalLoadPending, false);

                        Set(varPHR_IsLoading, false);
                        Set(varOps_IsLoading, false);
                        Set(varTasks_IsLoading, false);
                        Set(varPunches_IsLoading, false);
                        Set(varCfg_IsLoading, false);

                        Set(varAppView, "Home");
                        Set(varPageKey, "HOME");
                        Set(varPageTitle, "Home");
                        Set(varPageSubtitle, "Project command center");
                        Set(varHomeViewMode, "DASHBOARD");

                        Navigate(scr_Home, ScreenTransition.None),

                    "overview",
                        Set(varAppView, "Overview");
                        Set(varPageKey, "OVERVIEW");
                        Set(varPageTitle, "Overview");
                        Set(varPageSubtitle, "Project Handover Report by subsystem, discipline and form family");
                        Set(varOps_ViewMode, "OVERVIEW");

                        Navigate(scr_Overview, ScreenTransition.None),



                    "tasks",
                        Set(varAppView, "Tasks");
                        Set(varPageKey, "TASKS");
                        Set(varPageTitle, "Tasks");
                        Set(varPageSubtitle, "Inspection task management");

                        Navigate(scr_Tasks, ScreenTransition.None),

                    "punches",
                        Set(varAppView, "Punches");
                        Set(varPageKey, "PUNCHES");
                        Set(varPageTitle, "Punch List");
                        Set(varPageSubtitle, "Punch item management");

                        Navigate(scr_Punches, ScreenTransition.None),

                    "briefing",
                        Set(varAppView, "Briefing");
                        Set(varPageKey, "BRIEFING");
                        Set(varPageTitle, "Briefing");
                        Set(varPageSubtitle, "Project reporting and communication");

                        Navigate(scr_Briefing, ScreenTransition.None),

                    "config",
                        Set(varAppView, "Config");
                        Set(varPageKey, "CONFIG");
                        Set(varPageTitle, "Configuration");
                        Set(varPageSubtitle, "Report structure and scope management");

                        Navigate(scr_Config_NEW, ScreenTransition.None),

                    Notify("Key not mapped: [" & _key & "]", NotificationType.Error)
                )
            )
        )
    )
)

ControlPropertyState.AutoRuleBindingString:
With(
    {
        _key: Lower(Trim(cmp_NavApp_SuperAdmin.SelectedItemKey)),
        _hasProject: !IsBlank(varProjectId)
    },
    If(
        _key <> "home" && !_hasProject,

        Notify("Please select a project first.", NotificationType.Warning);
        Set(varAppView, "Home");
        Navigate(scr_Home, ScreenTransition.None),

        Switch(
            _key,

            "home",
                Set(varAppView, "Home");
                Navigate(scr_Home, ScreenTransition.None),

            "overview",
                Set(varAppView, "Overview");
                Set(varOps_ViewMode, "OVERVIEW");
                Navigate(scr_Overview, ScreenTransition.None),

            "tasks",
                Set(varAppView, "Tasks");
                Navigate(scr_Tasks, ScreenTransition.None),

            "punches",
                Set(varAppView, "Punches");
                Navigate(scr_Punches, ScreenTransition.None),

            "briefing",
                Set(varAppView, "Briefing");
                Navigate(scr_Briefing, ScreenTransition.None),

            "config",
                Set(varAppView, "Config");
                Navigate(scr_Config, ScreenTransition.None),

            "superadmin",
                Set(varAppView, "SuperAdmin");
                Navigate(scr_SuperAdmin, ScreenTransition.None),

            Notify("Key not mapped: [" & _key & "]", NotificationType.Error)
        )
    )
)

Rules.InvariantScript:
Set(varSA_UsersLoading, true);
Set(varSA_UsersError, "");

Clear(colSA_Users);
Clear(colSA_Roles);

IfError(
    Set(
        varSA_UsersRaw,
        WarRoom_Admin_Users_Get.Run(varProjectId).result
    ),
    Set(varSA_UsersError, "Error loading users.")
);

If(
    IsBlank(varSA_UsersError),

    ClearCollect(
        colSA_Users,
        ForAll(
            Table(ParseJSON(Coalesce(varSA_UsersRaw, "{}")).Table1),
            {
                UserId: Value(Value.UserId),
                Email: Text(Value.Email),
                LoginEmail: Text(Value.LoginEmail),
                DisplayName: Text(Value.DisplayName),
                UserIsActive: Boolean(Value.UserIsActive),
                UserProjectRoleId: If(IsBlank(Text(Value.UserProjectRoleId)), Blank(), Value(Value.UserProjectRoleId)),
                ProjectId: If(IsBlank(Text(Value.ProjectId)), Blank(), Value(Value.ProjectId)),
                RoleId: If(IsBlank(Text(Value.RoleId)), Blank(), Value(Value.RoleId)),
                RoleCode: Text(Value.RoleCode),
                RoleName: Text(Value.RoleName),
                RoleIsActive: Boolean(Value.RoleIsActive)
            }
        )
    )
);

IfError(
    Set(
        varSA_RolesRaw,
        WarRoom_Admin_Roles_Get.Run().result
    ),
    Set(varSA_UsersError, "Error loading roles.")
);

If(
    IsBlank(varSA_UsersError),

    ClearCollect(
        colSA_Roles,
        ForAll(
            Table(ParseJSON(Coalesce(varSA_RolesRaw, "{}")).Table1),
            {
                RoleId: Value(Value.RoleId),
                RoleCode: Text(Value.RoleCode),
                RoleName: Text(Value.RoleName),
                Description: Text(Value.Description),
                SortOrder: Value(Value.SortOrder)
            }
        )
    )
);

Set(varSA_UsersLoading, false);

ClearCollect(
    colSA_ProjectSearchRaw,
    WarRoom_Projects_Search.Run(txtSA_SearchProject_1.Text)
);

Clear(colSA_ProjectSearch);

ForAll(
    Table(ParseJSON(First(colSA_ProjectSearchRaw).result).Table1),
    Collect(
        colSA_ProjectSearch,
        {
            Id: Value(Value.Id),
            Code: Text(Value.Code),
            Name: Text(Value.Name),
            Description: Text(Value.Description),
            Company: Text(Value.Company),
            Location: Text(Value.Location),
            IsEnabledInWarRoom: Value(Value.IsEnabledInWarRoom)
        }
    )
);

ClearCollect(
    colSA_EnableResultRaw,
    WarRoom_EnabledProjects_Enable.Run(
        ThisItem.Id,
        User().Email
    )
);

Clear(colSA_EnableResult);

ForAll(
    Table(ParseJSON(First(colSA_EnableResultRaw).result).Table1),
    Collect(
        colSA_EnableResult,
        {
            Success: Boolean(Value.Success),
            Message: Text(Value.Message)
        }
    )
);

Notify(
    Coalesce(
        First(colSA_EnableResult).Message,
        "Project enabled."
    ),
    NotificationType.Success
);

ClearCollect(
    colEnabledProjectsRaw,
    WarRoom_EnabledProjects_GetActive.Run()
);

Clear(colEnabledProjects);

ForAll(
    Table(ParseJSON(First(colEnabledProjectsRaw).result).Table1),
    Collect(
        colEnabledProjects,
        {
            ProjectId: Value(Value.ProjectId),
            ProjectCode: Text(Value.ProjectCode),
            ProjectName: Text(Value.ProjectName),
            ProjectDescription: Text(Value.ProjectDescription),
            IsDefault: Boolean(Value.IsDefault)
        }
    )
);

ClearCollect(
    colEnabledProjectsUI,
    AddColumns(
        colEnabledProjects,
        ProjectDisplayName,
        ProjectCode & " · " & ProjectName
    )
);

Select(btnSA_SearchProjects_1);


ClearCollect(
    colEnabledProjectsRaw,
    WarRoom_EnabledProjects_GetActive.Run()
);

Clear(colEnabledProjects);

ForAll(
    Table(ParseJSON(First(colEnabledProjectsRaw).result).Table1),
    Collect(
        colEnabledProjects,
        {
            ProjectId: Value(Value.ProjectId),
            ProjectCode: Text(Value.ProjectCode),
            ProjectName: Text(Value.ProjectName),
            ProjectDescription: Text(Value.ProjectDescription),
            IsDefault: Boolean(Value.IsDefault)
        }
    )
);

ClearCollect(
    colEnabledProjectsUI,
    AddColumns(
        colEnabledProjects,
        ProjectDisplayName,
        ProjectCode & " · " & ProjectName
    )
);
